INSERT INTO `movies` (`movie_id`, `title`, `genre`, `language`, `industry`, `quality_tag`, `duration_minutes`, `description`, `trailer_url`, `poster`, `release_date`, `is_featured`, `created_at`) VALUES
(1, 'Gladiator (2000)', 'Action', 'English', 'Hollywood', '4K', 124, 'A betrayed Roman general is reduced to slavery and rises through the ranks of the arena to avenge the murder of his family and emperor. His battles inside the Colosseum captivate the public and challenge the corrupt new ruler. Visually epic and emotionally resonant, it won five Academy Awards.', 'https://www.youtube.com/embed/P5ieIbInFpg', 'https://tse4.mm.bing.net/th/id/OIP.si0wNka2b7ExSvtQJbgS-QHaJU?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2027-03-01', 0, '2026-08-21 06:52:15'),
(2, 'Terminator 2: Judgment Day (1991)', 'Action', 'English', 'Hollywood', 'HD', 99, 'A reprogrammed cyborg is sent back in time to protect a young John Connor from an advanced liquid-metal assassin designed to eradicate humanity&#039;s future leader. Revolutionary visual effects and relentless pacing set a standard for sci-fi action. Its iconic catchphrases and heart remain timeless.', 'https://www.youtube.com/embed/CRRlbK5w8AE', 'https://tse4.mm.bing.net/th/id/OIP.NC-Qe9tP2AhPrJbjivNoqQHaLH?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2026-10-19', 0, '2026-08-21 06:52:15'),
(3, 'Aliens (1986)', 'Action', 'English', 'Hollywood', '2K', 124, 'Ellen Ripley awakens from stasis and accompanies a squad of elite space marines to investigate a silent terraforming colony plagued by deadly extraterrestrials. The quiet tension of the original transforms into a militaristic, claustrophobic combat masterpiece. It remains a hallmark of action-horror integration.', 'https://www.youtube.com/embed/0hUgh076z2I', 'https://tse4.mm.bing.net/th/id/OIP.40vbs3CPGgHm6JPMfDv1pAHaLS?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2027-01-22', 0, '2026-08-21 06:52:15'),
(4, 'Top Gun: Maverick (2022)', 'Action', 'English', 'Hollywood', 'IMAX', 139, 'After thirty years of service, Pete &amp;#039;Maverick&amp;#039; Mitchell returns to train a group of elite TOPGUN graduates for a specialized, high-risk mission. Facing ghosts of his past, he leads them through dangerous aerial combat maneuvers. The real-cockpit aerial photography delivered an unparalleled cinematic spectacle.', 'https://www.youtube.com/embed/giXco2jaZ_4', 'https://tse3.mm.bing.net/th/id/OIP.U2T6N7VF82Y2pkGxvUJxXAHaEK?r=0&amp;amp;rs=1&amp;amp;pid=ImgDetMain&amp;amp;o=7&amp;amp;rm=3', '2026-10-03', 0, '2026-08-21 06:52:15'),
(5, 'Speed (1994)', 'Action', 'English', 'Hollywood', 'IMAX', 141, 'A young LAPD cop must prevent a bomb from exploding aboard a city bus by keeping its speed strictly above 50 miles per hour. The non-stop adrenaline combined with clever problem solving created an iconic 90s thriller. It established Keanu Reeves and Sandra Bullock as major superstar talents.', 'https://www.youtube.com/embed/wCh_sxggMFo', 'https://tse1.explicit.bing.net/th/id/OIP.x6Xad76aYaaBpTVZ-_2-ygHaFi?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2027-01-26', 0, '2026-08-21 06:52:15'),
(6, 'The Matrix (1999)', 'Action', 'English', 'Hollywood', 'HD', 106, 'A computer hacker discovers that his reality is a simulated illusion created by sentient machines to harvest human energy. Joining a group of freedom fighters, he learns to manipulate physics and fulfill a grand prophecy. Its ground-breaking bullet-time special effects forever changed action cinema.', 'https://www.youtube.com/embed/vKQi3bBA1y8', 'https://tse2.mm.bing.net/th/id/OIP.7TrHbd7X7zqXPKAOf0krAQHaLH?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2026-11-08', 0, '2026-08-21 06:52:15'),
(7, 'Avengers: Endgame (2019)', 'Action', 'English', 'Hollywood', 'HD', 133, 'Following a catastrophic cosmic defeat, the remaining heroes assemble to attempt a daring time-travel heist and reverse the destruction of the universe. Rich emotional character arcs climax in a battle of unprecedented scale and spectacle. It served as a historic, satisfying culmination of over a decade of storytelling.', 'https://www.youtube.com/embed/TcMBFSGVi1c', 'https://tse1.mm.bing.net/th/id/OIP.AsVeA2uTH8DIHIezO_yDGAHaK-?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2027-03-31', 0, '2026-08-21 06:52:15'),
(8, 'Casino Royale (2006)', 'Action', 'English', 'Hollywood', 'IMAX', 116, 'James Bond earns his 00 status and embarks on his first mission to bankrupt a terrorist financier in a high-stakes poker game in Montenegro. Grounded, gritty, and physically intense, this reboot redefined the legendary spy franchise for modern audiences. Daniel Craig delivered a commanding, vulnerability-filled performance.', 'https://www.youtube.com/embed/36mnx8dBbGE', 'https://m.media-amazon.com/images/M/MV5BMWQ1ZDM4NDktMWY0NC00MjcxLWJlMDMtNmE2MGVhYzRjMWQ0XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '2026-11-23', 0, '2026-08-21 06:52:15'),
(9, 'The Raid: Redemption (2011)', 'Action', 'English', 'Hollywood', 'HD', 117, 'An elite SWAT squad becomes trapped in a high-rise apartment complex run by a ruthless warlord and his army of killers. Forced to fight floor by floor, the team utilizes brutal Silat martial arts to survive. It is widely regarded as one of the most intense martial arts movies ever filmed.', 'https://www.youtube.com/embed/m6Q7KnXpNOg', 'https://tse4.mm.bing.net/th/id/OIP.cDa_eA7WsvNSDY9vcTGf5QHaGF?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2027-02-27', 0, '2026-08-21 06:52:15'),
(10, 'Bourne Supremacy (2004)', 'Action', 'English', 'Hollywood', 'HD', 137, 'Framed for a botched CIA operation, amnesiac assassin Jason Bourne is forced out of hiding to uncover a conspiracy that reaches the top levels of intelligence. Combining shaky-cam realism, tactical hand-to-hand combat, and visceral car chases, it set a new direction for 2000s action thrillers.', 'https://www.youtube.com/embed/Y-HqyyfBbSo', 'https://tse1.mm.bing.net/th/id/OIP.Ayu_98Pai_7Go5ez45ZFWAHaLw?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2026-10-22', 0, '2026-08-21 06:52:15'),
(11, 'Sholay (1975)', 'Action', 'Hindi', 'Bollywood', 'IMAX', 168, 'Two former convicts are hired by a retired police officer to capture the ruthless bandit Gabbar Singh who terrorizes a small rural village. Packed with iconic dialogues, memorable action sequences, and emotional depth, it remains the ultimate classic of Indian cinema. It fundamentally shaped the action-drama genre in India.', 'https://www.youtube.com/embed/QEiTDwVn5Hw', 'https://tse2.mm.bing.net/th/id/OIP.gCNmXLj1gRInJ5cpKWBaMAHaD1?r=0&amp;amp;rs=1&amp;amp;pid=ImgDetMain&amp;amp;o=7&amp;amp;rm=3', '2026-10-18', 0, '2026-08-21 06:52:15'),
(12, 'Dangal (2016)', 'Action', 'Hindi', 'Bollywood', 'HD', 127, 'An ambitious father overcomes societal norms to train his daughters in wrestling, aiming to fulfill his dream of winning an international gold medal for India. The gripping wrestling choreography and powerful emotional beats resonated globally, making it a record-breaking blockbuster. It stands as a masterclass in sports drama and action.', 'https://www.youtube.com/embed/x_7YlGv9u1g', 'https://tse3.mm.bing.net/th/id/OIP.ZM4jdtqSMnWxKOvYh9redAHaEK?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2027-01-09', 0, '2026-08-21 06:52:15'),
(13, 'Extraction (2020)', 'Action', 'English', 'Hollywood', '2K', 161, 'Tyler Rake, a fearless black-market mercenary, is hired to rescue the kidnapped son of an international crime lord in Dhaka. The mission quickly turns into a deadly game of survival as the entire city goes on lockdown against him. The movie is famous for its jaw-dropping 12-minute continuous single-shot action sequence.', 'https://www.youtube.com/embed/L6P3nI6VnlY', 'https://tse4.mm.bing.net/th/id/OIP.seDvPvDXjJE2onpz5yyecgHaEK?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2026-09-17', 0, '2026-08-21 06:52:15'),
(14, 'Nobody (2021)', 'Action', 'English', 'Hollywood', '2K', 104, 'Hutch Mansell is an understated, mild-mannered family man who accepts life&#039;s indignities without pushing back. However, after defending a woman on a bus, he reignites a dangerous past that draws the wrath of a deadly Russian mobster. It is a fast-paced, satisfying thriller packed with brutal fight scenes.', 'https://www.youtube.com/embed/wZti8QKBWPo', 'https://tse2.mm.bing.net/th/id/OIP.yQWQihkrOwdzjJK7ADyVEgHaLH?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2026-11-30', 0, '2026-08-21 06:52:15'),
(15, 'Baby Driver (2017)', 'Action', 'English', 'Hollywood', 'HD', 110, 'A talented young getaway driver relies on his personal music playlist to execute impossible high-speed escapes for a crime boss. When he falls in love, he decides to pull off one last job to leave his criminal life behind forever. Every car chase, gunshot, and movement is perfectly synced to the film&#039;s soundtrack.', 'https://www.youtube.com/embed/D9YZw_X5UzQ', 'https://tse3.mm.bing.net/th/id/OIP.uyx4Gztn3RjGoEZcJTZBJwHaK-?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2027-03-05', 0, '2026-08-21 06:52:15'),
(16, 'Atomic Blonde (2017)', 'Action', 'English', 'Hollywood', 'HD', 154, 'Set on the eve of the Berlin Wall&#039;s collapse in 1989, an elite MI6 spy is sent to Germany to retrieve a stolen list of double agents. Navigating a web of betrayal, she uses raw force and tactical skill to fight off scores of assassins. The film stands out for its gritty long-take staircase fight scene.', 'https://www.youtube.com/embed/y6DE2vDgNp8', 'https://th.bing.com/th/id/OIP._E6Sqe_NS9fAh3cx-aLiSgHaLH?r=0&amp;o=7rm=3&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2027-04-26', 0, '2026-08-21 06:52:15'),
(17, 'Hardcore Henry (2015)', 'Action', 'English', 'Hollywood', 'HD', 160, 'Resurrected as a cyborg with no memory of his past, Henry must save his wife from a telekinetic warlord in Moscow. The entire film is shot strictly from a first-person point-of-view, making the viewer feel like they are playing a live-action video game. It delivers non-stop, intense parkour and gunfights.', 'https://www.youtube.com/embed/4JVgQzBG5Ho', 'https://tse1.mm.bing.net/th/id/OIP.uitLGEaG-Opfp2Q6GIGesgHaK-?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2026-10-14', 0, '2026-08-21 06:52:15'),
(18, 'Sicario (2015)', 'Action', 'English', 'Hollywood', '2K', 137, 'An idealistic FBI agent is recruited by a government task force to aid in the escalating war against border cartel violence. As the operation unfolds, she is forced to confront dark moral gray areas and high-stakes tactical ambushes. It is a slow-burn thriller filled with overwhelming tension and sharp gunplay.', 'https://www.youtube.com/embed/Yfhu5JIxnZc', 'https://tse4.mm.bing.net/th/id/OIP.pB8OE6-9RwfKlxqYttEqMwHaLH?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2026-08-29', 0, '2026-08-21 06:52:15'),
(19, 'Dredd (2012)', 'Action', 'English', 'Hollywood', 'HD', 126, 'In a dystopian future, law enforcers called Judges act as judge, jury, and executioner in a vast megalopolis. Judge Dredd and a rookie psychic officer get trapped inside a 200-story slum tower ruled by a dangerous drug baroness. They must fight their way through hundreds of armed gang members to survive.', 'https://www.youtube.com/embed/JqqgrUna28w', 'https://film-book.com/wp-content/uploads/2012/06/karl-urban-dredd-01-1280x851.jpg', '2027-04-24', 0, '2026-08-21 06:52:15'),
(20, 'Bullet Train (2022)', 'Action', 'English', 'Hollywood', '2K', 112, 'An unlucky assassin named Ladybug boards a Japanese bullet train with a simple mission to retrieve a briefcase. However, he quickly discovers that several competing assassins with connected motives are on the same train. The movie offers a hilarious, fast-paced blend of colorful action and clever twists.', 'https://www.youtube.com/embed/0IOsk2Vlc4o', 'https://tse3.mm.bing.net/th/id/OIP.QyvdxNZ9oi0fo56l7BVkDgHaLG?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2027-04-24', 0, '2026-08-21 06:52:15'),
(21, 'RRR (2022)', 'Action', 'Hindi', 'Bollywood', '4K', 165, 'Set in British-ruled India, two legendary revolutionaries form a deep friendship before uncovering each other&#039;s true identities and fighting back against colonial tyranny. Packed with breathtaking set pieces, kinetic choreography, and mythic scale, it won international acclaim and an Academy Award. It redefined epic Indian spectacle.', 'https://www.youtube.com/embed/AVVO3Yat_Bw', 'https://tse2.mm.bing.net/th/id/OIP.uiUpcqWq6wO3VM37nYIQSQHaJ4?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2027-02-23', 0, '2026-08-21 06:52:15'),
(22, 'Gangs of Wasseypur (2012)', 'Action', 'Hindi', 'Bollywood', '4K', 111, 'A sprawling coal-mafia saga spans three generations of blood feuds, political power plays, and brutal revenge in a rural mining town. Gritty realism, explosive gunfights, and darkly humorous dialogue make it a groundbreaking cult classic in Hindi cinema. Director Anurag Kashyap crafted an Indian crime masterpiece.', 'https://www.youtube.com/embed/yt-y3euKuzs', 'https://tse4.mm.bing.net/th/id/OIP.VBSFG5B5xcWz-YpGEm6XBQHaKs?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2026-10-21', 0, '2026-08-21 06:52:15'),
(23, 'K.G.F: Chapter 1 (2018)', 'Action', 'Hindi', 'Bollywood', 'HD', 96, 'A fierce young orphan rises through Mumbai&#039;s criminal underworld to become a feared enforcer, embarking on a dangerous mission to liberate enslaved workers at the Kolar Gold Fields. High-contrast stylized cinematography and mass hero moments created an unstoppable cinematic phenomenon. It propelled regional pan-Indian cinema into global spotlight.', 'https://www.youtube.com/embed/ULEQb_l-N08', 'https://tse3.mm.bing.net/th/id/OIP.RwagjALMazcWQ3E-ZZFWkQHaLH?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2027-02-22', 0, '2026-08-21 06:52:15'),
(24, 'War (2019)', 'Action', 'Hindi', 'Bollywood', '4K', 161, 'An elite Indian soldier is tasked with hunting down his former mentor, a legendary rogue agent who has inexplicably turned against his nation. Featuring globetrotting set pieces, sleek bike chases, and heavy martial arts combat, it raised the bar for modern Bollywood action production. The star power delivered huge box-office success.', 'https://www.youtube.com/embed/tQ0mzXRk-oM', 'https://tse3.mm.bing.net/th/id/OIP.FL2oEXsInvzoZh2-Bh_iCQHaJ3?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2026-11-04', 0, '2026-08-21 06:52:15'),
(25, 'Pathaan (2023)', 'Action', 'Hindi', 'Bollywood', '2K', 127, 'An exiled RAW operative is called back to active duty to defeat a rogue mercenary outfit planning a devastating biological weapon attack on India. Packed with high-octane stunts, jet-pack sequences, and charismatic star power, it smashed box office records worldwide. It reinvigorated the spy universe in Indian film.', 'https://www.youtube.com/embed/vqu4z34wENw', 'https://tse3.mm.bing.net/th/id/OIP.8SM7n6TdXWtYyTP_mpRUCwHaEK?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2027-03-19', 0, '2026-08-21 06:52:15'),
(26, 'Ghajini (2008)', 'Action', 'Hindi', 'Bollywood', '2K', 148, 'A wealthy businessman suffering from short-term memory loss uses tattoos and photos to hunt down the man who murdered his girlfriend.', 'https://www.youtube.com/embed/LRvZCoFaIHw', 'https://tse3.mm.bing.net/th/id/OIP.eBYt1muih5iIkYPZyu0KLwHaJl?r=0&amp;amp;rs=1&amp;amp;pid=ImgDetMain&amp;amp;o=7&amp;amp;rm=3', '2027-04-03', 0, '2026-08-21 06:52:15'),
(27, 'Kill (2024)', 'Action', 'Hindi', 'Bollywood', 'HD', 139, 'An army commando boards a passenger train bound for New Delhi to protect his true love, turning the journey into a violent fight against a gang of armed bandits.', 'https://www.youtube.com/embed/8V3EF3iEt7g', 'https://tse1.mm.bing.net/th/id/OIP.7PzZ_EEN7rG3Dhz4VizFaAHaLG?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2026-10-27', 0, '2026-08-21 06:52:15'),
(28, 'Fighter (2024)', 'Action', 'Hindi', 'Bollywood', '4K', 155, 'An elite squadron of Indian Air Force pilots forms a specialized unit to respond to rising terrorist threats along the border. Following a devastating ambush, they embark on a dangerous mission deep into enemy territory. The film features intense aerial dogfights and high-g-force jet maneuvers.', 'https://www.youtube.com/embed/eifvzpMt_lE', 'https://tse1.mm.bing.net/th/id/OIP.VbYGNmF_2LFHUMz4UhQbQwHaHa?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2027-04-05', 0, '2026-08-21 06:52:15'),
(29, 'Animal (2023)', 'Action', 'Hindi', 'Bollywood', '4K', 107, 'The troubled son of a powerful industrialist grows obsessively devoted to his distant father. When an assassination attempt threatens his father&#039;s life, he unleashes an unhinged, violent war against rival clans. The film is filled with heavy artillery battles, chaotic axe fights, and intense violence.', 'https://www.youtube.com/embed/8FkLRUJj-o0', 'https://tse3.mm.bing.net/th/id/OIP.C1krYvDXDVZdzoZOHQ5_jAHaJQ?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2026-10-06', 0, '2026-08-21 06:52:15'),
(30, 'Monkey Man (2024)', 'Action', 'Hindi', 'Bollywood', 'HD', 144, 'An anonymous young man earns a meager living in an underground fight club while plotting revenge against the corrupt elites who destroyed his village. Inspired by ancient mythology, he unleashes a brutal campaign to bring down the city&#039;s powerful syndicate. The film stands out for its raw, close-quarters combat and aggressive choreography.', 'https://www.youtube.com/embed/iI4s8cavgRI', 'https://tse1.mm.bing.net/th/id/OIP.tvLf8IB6A8esnv1COhG0RAHaEK?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2026-12-02', 0, '2026-08-21 06:52:15'),
(31, 'Bholaa (2023)', 'Action', 'Hindi', 'Bollywood', 'IMAX', 120, 'An ex-convict on his way to meet his young daughter gets recruited by a wounded police officer to drive a truck full of poisoned cops to safety through a night of chaos. Pursued by gangs of ruthless criminals across a single night, he uses brute force and improvised weapons to defend the convoy.', 'https://www.youtube.com/embed/ZmamuKvM4Fg', 'https://tse1.mm.bing.net/th/id/OIP.T5dB6JVST5KcmXIFtjjz-gHaLH?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2026-10-19', 0, '2026-08-21 06:52:15'),
(32, 'Force (2011)', 'Action', 'Hindi', 'Bollywood', 'HD', 157, 'A ruthless, rule-breaking officer in a Narcotics Control Bureau team takes down a major drug cartel, killing the kingpin’s brother. Seeking vengeance, the dead gangster’s psychopath brother targets the officer&#039;s personal life and loved ones. It is a gritty action thriller known for its hard-hitting fistfights and heavy lifting stunts.', 'https://www.youtube.com/embed/wYyH6ujINzU', 'https://tse2.mm.bing.net/th/id/OIP.uretqQgYp3660Ss9CoxLFQHaGn?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2027-04-17', 0, '2026-08-21 06:52:15'),
(33, 'Vikram Vedha', 'Action', 'Hindi', 'Bollywood', '4K', 104, 'A pragmatic police inspector hunts down a feared gangster who surrenders voluntarily and challenges the officer&#039;s moral black-and-white worldview with enigmatic stories. Gritty action encounters and deep moral dilemmas create an engrossing cat-and-mouse dynamic. Hrithik Roshan and Saif Ali Khan delivered stellar lead performances.', 'https://www.youtube.com/embed/nf51aIeEWa0', 'https://m.media-amazon.com/images/M/MV5BYjc2YjVhNWQtYzVmZC00YzAyLTljNTItMmUxMTk1NjcyMThhXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '2026-12-06', 0, '2026-08-21 06:52:15'),
(34, 'Baby (2015)', 'Action', 'Hindi', 'Bollywood', 'HD', 149, 'An elite counter-terrorism unit embarks on rapid, global operations to track down and neutralize a mastermind plotting terror attacks in India. Grounded narrative, realistic tactical execution, and fast-paced editing set it apart from typical commercial action fare. Akshay Kumar anchored the realistic thrill-ride with conviction.', 'https://www.youtube.com/embed/5uGsJZe-33M', 'https://tse3.mm.bing.net/th/id/OIP.y69Wb-SlX2RZ1p4Kv7vDHQHaKu?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2027-01-16', 0, '2026-08-21 06:52:15'),
(35, 'Agneepath (2012)', 'Action', 'Hindi', 'Bollywood', '4K', 146, 'A young boy grows up with a single-minded desire to avenge his father&#039;s brutal murder by taking over the underworld of Kanchnoor. Raw violence, intense emotional stakes, and towering performances make this reboot a gritty action classic. Hrithik Roshan and Sanjay Dutt delivered fierce screen presence.', 'https://www.youtube.com/embed/D8GTFTeIV1I', 'https://tse1.mm.bing.net/th/id/OIP.z5LsHw7X1WPbIobmGZtpfAHaKs?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2027-02-12', 0, '2026-08-21 06:52:15'),
(36, 'Singham (2011)', 'Action', 'Hindi', 'Bollywood', 'HD', 105, 'An honest, uncompromising police officer stands up to a powerful corrupt politician in a small town, sparking a relentless battle for justice. Gravity-defying stunts, powerful punch lines, and intense hand-to-hand fights spawned Bollywood&#039;s famous Cop Universe. Ajay Devgn&#039;s fierce performance made the character iconic.', 'https://www.youtube.com/embed/M1qJCsHI2Mw', 'https://tse3.mm.bing.net/th/id/OIP.sqNRAIlsKmxpdM_jqvzjVgHaKu?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2026-10-18', 0, '2026-08-21 06:52:15'),
(37, 'Dhoom 2 (2006)', 'Action', 'Hindi', 'Bollywood', '4K', 132, 'A high-tech master thief targets priceless artifacts across the globe while a sharp ACP and his team play a high-stakes game of cat and mouse. Known for stylish roller-skating sequences, sandboarding heists, and chart-topping music, it elevated Bollywood action aesthetics. Hrithik Roshan delivered a career-defining slick villain performance.', 'https://www.youtube.com/embed/w6bhlOHRV8s', 'https://tse1.mm.bing.net/th/id/OIP.TKfBqDdNrmgSxfz5OjfK5QHaKN?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2026-12-15', 0, '2026-08-21 06:52:15'),
(38, 'Don 2 (2011)', 'Action', 'Hindi', 'Bollywood', '4K', 109, 'Having conquered the Asian underworld, crime lord Don sets his sights on dominating the European mafia by plotting an impossible bank heist in Berlin. Stylish direction, clever plot twists, and slick action sequences make it a stand-out heist action thriller. Shah Rukh Khan played the titular charismatic villain with suave intensity.', 'https://www.youtube.com/embed/SEa7l_36e6E', 'https://tse2.mm.bing.net/th/id/OIP.Pg8kF1WA3Ph2iG3owrS_lQHaKo?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2026-10-31', 0, '2026-08-21 06:52:15'),
(39, 'Jawan (2023)', 'Action', 'Hindi', 'Bollywood', '4K', 139, 'A mysterious warden and a group of skilled women execute high-stakes heists to highlight corruption and force social systemic changes across India. Combining mass-appeal vigilante action with sharp political commentary, the film delivered an explosive visual experience. It solidified Shah Rukh Khan&#039;s dominance in high-action roles.', 'https://www.youtube.com/embed/COv52Qyctws', 'https://tse4.mm.bing.net/th/id/OIP.2PwRro1gOlrkNg3Hdh5XeAHaJQ?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2027-02-16', 0, '2026-08-21 06:52:15'),
(40, 'The Surgical Strike (2019)', 'Action', 'Hindi', 'Bollywood', 'IMAX', 150, 'Based on true events, an Indian military commander leads a covert operation across enemy lines to execute a precision strike against terrorist launchpads. Intense tactical combat, realistic military protocol, and patriotic sentiment drove massive audience engagement. It earned critical acclaim and multiple National Film Awards.', 'https://www.youtube.com/embed/ga1PMLM0Op4', 'https://tse4.mm.bing.net/th/id/OIP.64MVVjWNLs72gTsnd_OGiwHaLy?r=0&amp;rs=1&amp;pid=ImgDetMain&amp;o=7&amp;rm=3', '2026-09-05', 1, '2026-08-21 06:52:15'),
